mutations.replacement:
where = ROOT if root is None else root
out = []
for pat in ("*.py", "*.md"):
    for path in sorted(where.rglob(pat)):
        parts = path.relative_to(where).parts
        if parts[0] in (".venv", ".git", "build", "dist"):
            continue
        out.append(path)
return out

